package com.foodbridge.charity;
import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;import java.io.IOException;import java.nio.file.*;import java.util.Set;import java.util.UUID;
@Service public class CharityDocumentService {
    private static final Set<String> ALLOWED=Set.of("application/pdf","image/jpeg","image/png");
    private final CharityDocumentRepository repo;private final Path root;
    public CharityDocumentService(CharityDocumentRepository repo,@Value("${foodbridge.private-upload-dir:./private-uploads}") String dir)throws IOException{this.repo=repo;root=Path.of(dir).toAbsolutePath().normalize();Files.createDirectories(root);}
    @Transactional public CharityDocument upload(String username,MultipartFile file)throws IOException{if(file==null||file.isEmpty())throw new IllegalArgumentException("Choose a document to upload.");if(file.getSize()>10L*1024*1024)throw new IllegalArgumentException("Maximum file size is 10 MB.");String type=file.getContentType()==null?"":file.getContentType().toLowerCase();if(!ALLOWED.contains(type))throw new IllegalArgumentException("Only PDF, JPEG, and PNG files are accepted.");String original=Path.of(file.getOriginalFilename()==null?"document":file.getOriginalFilename()).getFileName().toString();String ext=type.equals("application/pdf")?".pdf":type.equals("image/png")?".png":".jpg";String stored=UUID.randomUUID()+ext;Path target=root.resolve(stored).normalize();if(!target.startsWith(root))throw new IllegalArgumentException("Invalid filename.");Files.copy(file.getInputStream(),target,StandardCopyOption.REPLACE_EXISTING);try{return repo.save(new CharityDocument(username,original,stored,type,file.getSize()));}catch(RuntimeException e){Files.deleteIfExists(target);throw e;}}
    public java.util.List<CharityDocument> mine(String username){return repo.findByUploadedByOrderByUploadedAtDesc(username);}
    public Path resolvePrivate(String stored){Path p=root.resolve(stored).normalize();if(!p.startsWith(root))throw new IllegalArgumentException("Invalid storage path");return p;}
}
